pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        // Deploy as the test contract itself, so Ownable constructor sets _owner = address(this)
        c = new C(address(this));
    }

    function testFuzz_property(address fakeOwner) public {
        // The Ownable constructor transfers ownership to _msgSender(),
        // which in the context of setUp() and testing is address(this).
        // fakeOwner parameter is not used for setup; it only ensures the test is parameterized.
        // The property: for any deployment (created in setUp), the owner() must equal the deployer (address(this)).

        // The reference C returns address(this); the mutant returns the hardcoded address.
        assertTrue(c.owner() == address(this));
    }
}

