pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller) public {
        // caller must be a valid EOA, not the deployer of C to trigger the mutant difference
        vm.assume(caller != address(this));
        vm.assume(caller != address(0));

        // Retrieve the deployer-stored owner
        address storedOwner = address(this);

        // Prank as the fuzzed caller and call owner()
        vm.prank(caller);
        address returnedOwner = c.owner();

        // The correct contract always returns the stored owner; the mutant returns caller
        assertTrue(returnedOwner == storedOwner);
    }
}

