// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address deployer) public {
        // The deployer address must be the zero address to match setUp, but the fuzzer can provide any;
        // we need to verify that owner() returns the actual deployer passed to the constructor.
        // Deploy a fresh C with the fuzzed deployer used as the initial liquidityReceiveAddress.
        // Because the owner of C is set to the _msgSender() at the time of deployment (msg.sender),
        // we must actually deploy with the fuzzer as the sender.
        // However, the setUp deploys with address(this) as owner, which breaks the ability to test
        // after deployment. So in the test itself we deploy a fresh instance with the fuzzed deployer.
        // This is allowed: we can deploy multiple instances.
        vm.assume(deployer != address(0)); // owner cannot be zero address in original
        vm.prank(deployer);
        C freshC = new C(deployer);
        // The owner of freshC must equal deployer.
        assertTrue(freshC.owner() == deployer);
    }
}

